import {guides} from './guides.mjs';
const aliases={mechanics:'automotive',electronics:'electricity',hydraulics:'fluids',engine:'automotive',pneumatic:'pneumatics',fluid:'fluids',electric:'electricity'};
const sources={physics:[['OpenStax · Work and energy','https://openstax.org/books/university-physics-volume-1/pages/7-introduction']],automotive:[['DENSO · Starter diagnosis','https://www.denso-am.eu/news/starter-troubleshooting']],electricity:[['All About Circuits · AC textbook','https://www.allaboutcircuits.com/textbook/alt/']],electromechanics:[['All About Circuits · Three-phase systems','https://www.allaboutcircuits.com/textbook/alternating-current/chpt-10/three-phase-power-systems/']],pneumatics:[['Festo Didactic · Pneumatics','https://labvolt.festo.com/downloads/89791_F0.pdf']],fluids:[['OpenStax · Fluid mechanics','https://openstax.org/books/university-physics-volume-1/pages/14-summary']],mechatronics:[['Siemens · PLC scan cycle','https://docs.tia.siemens.cloud/r/simatic_s7_1200_manual_collection_enus_20/plc-concepts/execution-of-the-user-program/processing-the-scan-cycle-in-run-mode']],bicycles:[['Shimano · Component-specific adjustment','https://si.shimano.com/en/pdfs/dm/LARD001/DM-LARD001-01-ENG.pdf']]};
const drafts=new Map();
export function renderCourseGuide(host,key,lang='es',context=''){
 key=aliases[key]||key;if(!host||!guides[key])return;host.querySelector('[data-course-guide]')?.remove();
 if(!document.querySelector('[data-guide-style]')){const link=document.createElement('link');link.rel='stylesheet';link.href=new URL('./teaching.css',import.meta.url);link.dataset.guideStyle='';document.head.append(link);}
 const root=document.createElement('section');root.dataset.courseGuide=key;root.lang=lang;root.className='course-quality';host.append(root);const t=(es,en)=>lang==='es'?es:en,g=guides[key],text=k=>g[k][lang],add=(tag,value,parent=root)=>{const el=document.createElement(tag);el.textContent=value;parent.append(el);return el;};
 const draftKey=key+':'+context;const state=drafts.get(draftKey)||{response:'',revealed:false};drafts.set(draftKey,state);
 add('p',t('GUÍA DEL CURSO · ENTENDER, CALCULAR, COMPROBAR','COURSE GUIDE · UNDERSTAND, CALCULATE, VERIFY')).className='guide-kicker';add('h3',text('title'));
 const label=add('label',t('Idioma de esta guía ','Guide language ')),select=add('select','',label);for(const [value,title]of [['es','Español'],['en','English']]){const option=add('option',title,select);option.value=value;}select.value=lang;select.onchange=()=>renderCourseGuide(host,key,select.value,context);
 add('p',t('Esta guía conecta las lecciones del curso. Los ejemplos son ejercicios didácticos, no nuevas funciones de la animación.','This guide connects the course lessons. Examples are teaching exercises, not new animation features.'));
 const parts=[['prerequisite','Antes de empezar','Before you begin'],['route','Ruta de aprendizaje','Learning sequence'],['reasoning','Modelo mental','How the system works'],['example','Ejemplo resuelto con supuestos','Worked example and assumptions'],['diagnosis','Cómo distinguir causas','Distinguishing causes'],['experiment','Práctica de observación','Observation practice']];
 for(const [field,es,en]of parts){const d=add('details','');d.open=['example','reasoning'].includes(field);add('summary',t(es,en),d);add('p',text(field),d);}
 const exercise=add('section','');exercise.className='guide-exercise';add('h4',t('Reto: explica antes de ver la solución','Challenge: explain before revealing the solution'),exercise);add('p',text('question'),exercise);const responseLabel=add('label',t('Tu razonamiento (se conserva durante esta visita)','Your reasoning (kept during this visit)'),exercise),response=add('textarea','',responseLabel);response.rows=3;response.value=state.response;response.oninput=()=>{state.response=response.value;};const reveal=add('button',t('Comparar con la explicación','Compare with the explanation'),exercise);reveal.dataset.guideAnswer=key;const answer=add('p',state.revealed?text('answer'):'',exercise);answer.setAttribute('role','status');reveal.onclick=()=>{state.revealed=true;answer.textContent=text('answer');};
 const rubric=add('details','',exercise);add('summary',t('Cómo evaluar tu respuesta','How to assess your response'),rubric);add('p',t('Comprueba: 1) nombraste la magnitud o condición que cambia; 2) usaste unidades y supuestos correctos; 3) explicaste qué dato distingue las causas; 4) dijiste qué verificar después. Ver la solución no marca la lección como aprobada.','Check: 1) you named the changing quantity or condition; 2) you used correct units and assumptions; 3) you explained which evidence distinguishes causes; 4) you stated what to verify afterward. Revealing the solution does not mark the lesson complete.'),rubric);
 add('h4',t('Error frecuente','Common misconception'));add('p',text('misconception'));add('h4',t('Límites del ejemplo y del laboratorio','Example and laboratory limits'));add('p',text('boundary'));
 const reference=add('details','');add('summary',t('Referencias para profundizar','Further reading'),reference);for(const [title,url]of sources[key]){const a=add('a',title,reference);a.href=url;a.target='_blank';a.rel='noopener';}
}
